// Anthropic Tool Choice Hack for Strict JSON
import Anthropic from '@anthropic-ai/sdk';

const anthropic = new Anthropic();
const msg = await anthropic.messages.create({
  model: 'claude-3-5-sonnet-20241022',
  max_tokens: 1024,
  tools: [{
    name: 'submit_data',
    description: 'Output strictly validated structured JSON',
    input_schema: {
      type: 'object',
      properties: {
        title: { type: 'string' },
        date: { type: 'string' },
        participants: { type: 'array', items: { type: 'string' } }
      },
      required: ['title', 'date', 'participants']
    }
  }],
  tool_choice: { type: 'tool', name: 'submit_data' },
  messages: [{ role: 'user', content: 'Dinner with Alice tomorrow at 7pm' }]
});
const event = msg.content.find(b => b.type === 'tool_use')?.input;

// Gemini 2.0 Flash Context Caching with google-genai
import { GoogleGenAI } from '@google/genai';

const ai = new GoogleGenAI();
const cache = await ai.caches.create({
  model: 'gemini-2.0-flash',
  config: {
    displayName: 'documentation_cache',
    ttl: '300s', // 5 minutes
    contents: [{ role: 'user', parts: [{ text: LARGE_DOCS_OVER_32K_TOKENS }] }]
  }
});

// OpenAI o3-mini Reasoning Effort
import OpenAI from 'openai';

const openai = new OpenAI();
const completion = await openai.chat.completions.create({
  model: 'o3-mini',
  reasoning_effort: 'medium', // 'low' | 'medium' | 'high'
  messages: [{ role: 'user', content: 'Prove this mathematical lemma.' }]
});

// OpenAI Audio Input
import OpenAI from 'openai';
import fs from 'fs';

const openai = new OpenAI();
const base64Audio = fs.readFileSync('input.wav').toString('base64');

const response = await openai.chat.completions.create({
  model: 'gpt-4o-audio-preview',
  modalities: ['text'],
  messages: [{
    role: 'user',
    content: [
      { type: 'text', text: 'Transcribe and extract sentiment.' },
      { type: 'input_audio', input_audio: { data: base64Audio, format: 'wav' } }
    ]
  }]
});

