// Google Gemini PDF Document Processing
import { GoogleGenAI } from '@google/genai';
import fs from 'fs';

const ai = new GoogleGenAI();
const pdfBuffer = fs.readFileSync('contract.pdf');

const response = await ai.models.generateContent({
  model: 'gemini-2.0-flash',
  contents: [
    {
      inlineData: {
        data: pdfBuffer.toString('base64'),
        mimeType: 'application/pdf'
      }
    },
    'Summarize key obligations and liabilities.'
  ]
});

codeExamples.python:
# Gemini Native Python Code Execution
from google import genai

client = genai.Client()
response = client.models.generate_content(
    model="gemini-2.0-flash",
    contents="Calculate the 100th Fibonacci number and verify it is prime.",
    config={"tools": [{"code_execution": {}}]}
)
# Inspect both model's Python code and the executed output
for part in response.candidates[0].content.parts:
    if part.executable_code:
        print("CODE:", part.executable_code.code)
    if part.code_execution_result:
        print("OUTPUT:", part.code_execution_result.output)
print("FINAL:", response.text)

